-- ============================================================================
-- Client range-dropdown options (budget + preferred_area).
--
-- Converts the clients model's two range fields from free-typed min/max
-- number inputs into DROPDOWN min/max pickers by attaching an options list
-- to each field. The render change lives in RangeField.tsx (renders two
-- <select>s when field.options is non-empty); this migration only adds the
-- option ladders to the live schema. Stored record values stay {min,max}
-- NUMERIC — option values are numeric strings — so v_clients budget_min/max
-- + preferred_area_min/max and every other range reader are unaffected.
--
-- Budget (ر.س): 500K→1M /50K, 1M→3M /100K, 3M→10M /1M  (38 steps).
-- Preferred area (م²): 100→2000 standard ladder         (12 steps).
--
-- Generated by scripts/build-client-range-dropdowns.mjs — re-run to regenerate.
-- Idempotent: re-running overwrites the two fields' options with the same list.
-- ============================================================================

-- Backup the clients model row before mutating its schema.
CREATE TABLE IF NOT EXISTS public._backup_clients_model_20260617 AS
  SELECT * FROM public.models WHERE name = 'clients';

DO $$
DECLARE
  v_id uuid;
  v_schema jsonb;
  v_budget jsonb := '[{"id":"budget_opt_500000","label_ar":"500,000","label_en":"500,000","value":"500000"},{"id":"budget_opt_550000","label_ar":"550,000","label_en":"550,000","value":"550000"},{"id":"budget_opt_600000","label_ar":"600,000","label_en":"600,000","value":"600000"},{"id":"budget_opt_650000","label_ar":"650,000","label_en":"650,000","value":"650000"},{"id":"budget_opt_700000","label_ar":"700,000","label_en":"700,000","value":"700000"},{"id":"budget_opt_750000","label_ar":"750,000","label_en":"750,000","value":"750000"},{"id":"budget_opt_800000","label_ar":"800,000","label_en":"800,000","value":"800000"},{"id":"budget_opt_850000","label_ar":"850,000","label_en":"850,000","value":"850000"},{"id":"budget_opt_900000","label_ar":"900,000","label_en":"900,000","value":"900000"},{"id":"budget_opt_950000","label_ar":"950,000","label_en":"950,000","value":"950000"},{"id":"budget_opt_1000000","label_ar":"1,000,000","label_en":"1,000,000","value":"1000000"},{"id":"budget_opt_1100000","label_ar":"1,100,000","label_en":"1,100,000","value":"1100000"},{"id":"budget_opt_1200000","label_ar":"1,200,000","label_en":"1,200,000","value":"1200000"},{"id":"budget_opt_1300000","label_ar":"1,300,000","label_en":"1,300,000","value":"1300000"},{"id":"budget_opt_1400000","label_ar":"1,400,000","label_en":"1,400,000","value":"1400000"},{"id":"budget_opt_1500000","label_ar":"1,500,000","label_en":"1,500,000","value":"1500000"},{"id":"budget_opt_1600000","label_ar":"1,600,000","label_en":"1,600,000","value":"1600000"},{"id":"budget_opt_1700000","label_ar":"1,700,000","label_en":"1,700,000","value":"1700000"},{"id":"budget_opt_1800000","label_ar":"1,800,000","label_en":"1,800,000","value":"1800000"},{"id":"budget_opt_1900000","label_ar":"1,900,000","label_en":"1,900,000","value":"1900000"},{"id":"budget_opt_2000000","label_ar":"2,000,000","label_en":"2,000,000","value":"2000000"},{"id":"budget_opt_2100000","label_ar":"2,100,000","label_en":"2,100,000","value":"2100000"},{"id":"budget_opt_2200000","label_ar":"2,200,000","label_en":"2,200,000","value":"2200000"},{"id":"budget_opt_2300000","label_ar":"2,300,000","label_en":"2,300,000","value":"2300000"},{"id":"budget_opt_2400000","label_ar":"2,400,000","label_en":"2,400,000","value":"2400000"},{"id":"budget_opt_2500000","label_ar":"2,500,000","label_en":"2,500,000","value":"2500000"},{"id":"budget_opt_2600000","label_ar":"2,600,000","label_en":"2,600,000","value":"2600000"},{"id":"budget_opt_2700000","label_ar":"2,700,000","label_en":"2,700,000","value":"2700000"},{"id":"budget_opt_2800000","label_ar":"2,800,000","label_en":"2,800,000","value":"2800000"},{"id":"budget_opt_2900000","label_ar":"2,900,000","label_en":"2,900,000","value":"2900000"},{"id":"budget_opt_3000000","label_ar":"3,000,000","label_en":"3,000,000","value":"3000000"},{"id":"budget_opt_4000000","label_ar":"4,000,000","label_en":"4,000,000","value":"4000000"},{"id":"budget_opt_5000000","label_ar":"5,000,000","label_en":"5,000,000","value":"5000000"},{"id":"budget_opt_6000000","label_ar":"6,000,000","label_en":"6,000,000","value":"6000000"},{"id":"budget_opt_7000000","label_ar":"7,000,000","label_en":"7,000,000","value":"7000000"},{"id":"budget_opt_8000000","label_ar":"8,000,000","label_en":"8,000,000","value":"8000000"},{"id":"budget_opt_9000000","label_ar":"9,000,000","label_en":"9,000,000","value":"9000000"},{"id":"budget_opt_10000000","label_ar":"10,000,000","label_en":"10,000,000","value":"10000000"}]'::jsonb;
  v_area   jsonb := '[{"id":"area_opt_100","label_ar":"100","label_en":"100","value":"100"},{"id":"area_opt_150","label_ar":"150","label_en":"150","value":"150"},{"id":"area_opt_200","label_ar":"200","label_en":"200","value":"200"},{"id":"area_opt_250","label_ar":"250","label_en":"250","value":"250"},{"id":"area_opt_300","label_ar":"300","label_en":"300","value":"300"},{"id":"area_opt_350","label_ar":"350","label_en":"350","value":"350"},{"id":"area_opt_400","label_ar":"400","label_en":"400","value":"400"},{"id":"area_opt_500","label_ar":"500","label_en":"500","value":"500"},{"id":"area_opt_750","label_ar":"750","label_en":"750","value":"750"},{"id":"area_opt_1000","label_ar":"1,000","label_en":"1,000","value":"1000"},{"id":"area_opt_1500","label_ar":"1,500","label_en":"1,500","value":"1500"},{"id":"area_opt_2000","label_ar":"2,000","label_en":"2,000","value":"2000"}]'::jsonb;
  s int;
  f int;
  v_name text;
BEGIN
  SELECT id, schema INTO v_id, v_schema FROM public.models WHERE name = 'clients';
  IF v_id IS NULL THEN RAISE EXCEPTION 'clients model not found'; END IF;

  FOR s IN 0 .. jsonb_array_length(v_schema->'sections') - 1 LOOP
    FOR f IN 0 .. jsonb_array_length(v_schema->'sections'->s->'fields') - 1 LOOP
      v_name := v_schema #>> ARRAY['sections', s::text, 'fields', f::text, 'name'];
      IF v_name = 'budget' THEN
        v_schema := jsonb_set(v_schema, ARRAY['sections', s::text, 'fields', f::text, 'options'], v_budget, true);
      ELSIF v_name = 'preferred_area' THEN
        v_schema := jsonb_set(v_schema, ARRAY['sections', s::text, 'fields', f::text, 'options'], v_area, true);
      END IF;
    END LOOP;
  END LOOP;

  -- Updating models.schema fires models_view_sync → v_clients is regenerated.
  UPDATE public.models SET schema = v_schema, updated_at = now() WHERE id = v_id;
  RAISE NOTICE 'clients budget/preferred_area options applied (% / % steps)',
    jsonb_array_length(v_budget), jsonb_array_length(v_area);
END $$;
